from typing import Any, Dict

def process_settings(**kwargs: Any) -> Dict[str, Any]:
    return {
        key: value.upper() if isinstance(value, str) else value * 2 if isinstance(value, int) else str(value)
        for key, value in kwargs.items()
    }

print(process_settings(name='alice', age=30, active=True))

def display_user_info(name, **kwargs):
    print(f'Name: {name}')
    for key, value in kwargs.items():
        print(f'{key}: {value}')

# Example usage
display_user_info('Alice', age=25, city='New York')

def merge_records(record_id, **fields):
    result = {'record_id': record_id}
    for key, value in fields.items():
        if not isinstance(value, (str, int)):
            raise TypeError(f'Value for {key} must be str or int, got {type(value).__name__}')
        result[key] = value
    return result

# Example usage
result = merge_records('REC001', status='active', count=5)
print(result)

def log_event(event_name, **kwargs):
    parts = [f'Event: {event_name}']
    for key, value in kwargs.items():
        parts.append(f'{key}={value}')
    print(' | '.join(parts))
    return all(isinstance(v, str) for v in kwargs.values())

# Example usage
log_event('login', user='alice', status='success')
print(log_event('error', code=404, msg='Not Found'))

def create_request(method, **kwargs):
    request = {'method': method}
    headers = {}
    body = {}
    for key, value in kwargs.items():
        if isinstance(value, dict):
            body[key] = value
        else:
            headers[key] = value
    if headers:
        request['headers'] = headers
    if body:
        request['body'] = body
    return request

# Example usage
req = create_request('POST', auth='Bearer xyz', payload={'id': 123, 'name': 'Test'})
print(req)

def apply_to_all(func, **kwargs):
    def inner(value):
        return func(value, **kwargs)
    return inner

# Example usage
multiplier = apply_to_all(lambda x, y=2, z=3: x * y * z)
result = multiplier(5)
print(result)  # 30
